     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.nio.charset.StandardCharsets;
     4	import java.security.MessageDigest;
     5	import java.security.NoSuchAlgorithmException;
     6	import java.util.Locale;
     7	
     8	import org.springframework.samples.petclinic.model.Owner;
     9	
    10	/**
    11	 * Derives the stable identifier shared by every owner in the same household. A household
    12	 * is the set of owners with the same last name and postcode: the first 12 hex characters of
    13	 * SHA-256 over {@code normalizedLastName + '|' + postcode} (last name normalized
    14	 * case-insensitively with collapsed whitespace, matching {@link EnsureOwnerHouseholdUnique}),
    15	 * so joiners created with {@code sharesHousehold} always resolve to the same value.
    16	 */
    17	public final class HouseholdId {
    18	
    19	    private HouseholdId() {
    20	    }
    21	
    22	    public static String of(Owner owner) {
    23	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
    24	        String seed = key(owner.getLastName()) + "|" + postcode;
    25	        try {
    26	            byte[] digest = MessageDigest.getInstance("SHA-256")
    27	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
    28	            StringBuilder sb = new StringBuilder(12);
    29	            for (int i = 0; i < 6; i++) {
    30	                sb.append(String.format("%02X", digest[i]));
    31	            }
    32	            return sb.toString();
    33	        }
    34	        catch (NoSuchAlgorithmException e) {
    35	            throw new IllegalStateException(e);
    36	        }
    37	    }
    38	
    39	    private static String key(String value) {
    40	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    41	    }
    42	}
