     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import org.springframework.samples.petclinic.model.Owner;
     4	import org.springframework.samples.petclinic.repository.OwnerRepository;
     5	
     6	/**
     7	 * Finds an existing owner that {@code owner} possibly duplicates: another owner sharing this
     8	 * one's last name (case-insensitive) and postcode but with a different telephone — a soft match
     9	 * that is not a hard {@link IdentityKey} duplicate. Owners in the same {@link HouseholdId} are
    10	 * excluded: a declared household member is not a suspected duplicate. Returns the earliest such
    11	 * owner's id, or {@code null} when there is none.
    12	 */
    13	public final class PossibleDuplicate {
    14	
    15	    private PossibleDuplicate() {
    16	    }
    17	
    18	    public static Integer of(Owner owner, OwnerRepository ownerRepository) {
    19	        String postcode = owner.getPostcode();
    20	        if (postcode == null || postcode.isBlank()) {
    21	            return null;
    22	        }
    23	        String householdId = HouseholdId.of(owner);
    24	        return ownerRepository.findAll().stream()
    25	                .filter(other -> other.getId() != null && !other.getId().equals(owner.getId()))
    26	                .filter(other -> !householdId.equals(HouseholdId.of(other)))
    27	                .filter(other -> postcode.equals(other.getPostcode()))
    28	                .filter(other -> other.getLastName().equalsIgnoreCase(owner.getLastName()))
    29	                .filter(other -> !owner.getTelephone().equals(other.getTelephone()))
    30	                .map(Owner::getId)
    31	                .min(Integer::compareTo)
    32	                .orElse(null);
    33	    }
    34	}
