     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
     7	
     8	/**
     9	 * Rejects a create when another owner shares this owner's whole {@link IdentityKey}.
    10	 * This is the single consolidated duplicate check: a shared telephone, email or household
    11	 * on its own is allowed — only an exact full-key match is a conflict.
    12	 */
    13	public class EnsureOwnerIdentityUnique {
    14	
    15	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
    16	            throws DuplicateIdentityException {
    17	        String identityKey = IdentityKey.of(owner);
    18	        boolean taken = ownerRepository.findAll().stream()
    19	                .filter(other -> !other.isDeleted())
    20	                .anyMatch(other -> identityKey.equals(IdentityKey.of(other)));
    21	        if (taken) {
    22	            throw new DuplicateIdentityException("An owner with the same identity already exists");
    23	        }
    24	    }
    25	}
