     8	/**
     9	 * Rejects a create when another owner resolves to the same {@link HouseholdId} (same last
    10	 * name and postcode), unless the request opted in with {@code sharesHousehold}.
    11	 */
    12	public class EnsureOwnerHouseholdUnique {
    13	
    14	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
    15	            throws DuplicateHouseholdException {
    16	        if (Boolean.TRUE.equals(sharesHousehold)) {
    17	            return;
    18	        }
    19	        String householdId = HouseholdId.of(owner);
    20	        boolean clash = ownerRepository.findAll().stream()
    21	                .filter(other -> !other.isDeleted())
    22	                .anyMatch(other -> householdId.equals(HouseholdId.of(other)));
    23	        if (clash) {
    24	            throw new DuplicateHouseholdException(
    25	                    "An owner with the same last name and postcode already exists");
    26	        }
    27	    }
    28	}
