     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import org.springframework.samples.petclinic.model.Owner;
     4	
     5	/**
     6	 * Formats an owner's stored E.164 telephone for humans: keep the leading '+' and country
     7	 * code, add a space, then the national digits grouped in threes (e.g. '+61412345678' ->
     8	 * '+61 412 345 678'). '+61' and '+1' country codes are recognised; anything else keeps its
     9	 * digits ungrouped after the '+'. The raw stored 'telephone' is left untouched.
    10	 */
    11	public final class TelephoneDisplay {
    12	
    13	    private TelephoneDisplay() {
    14	    }
    15	
    16	    public static String of(Owner owner) {
    17	        String telephone = owner.getTelephone();
    18	        if (telephone == null || !telephone.startsWith("+")) {
    19	            return telephone;
    20	        }
    21	        String digits = telephone.substring(1);
    22	        int codeLength = digits.startsWith("61") ? 2 : digits.startsWith("1") ? 1 : 0;
    23	        String national = groupInThrees(digits.substring(codeLength));
    24	        return "+" + digits.substring(0, codeLength) + " " + national;
    25	    }
    26	
    27	    private static String groupInThrees(String national) {
    28	        StringBuilder grouped = new StringBuilder();
    29	        for (int i = 0; i < national.length(); i++) {
    30	            if (i > 0 && i % 3 == 0) {
    31	                grouped.append(' ');
    32	            }
    33	            grouped.append(national.charAt(i));
    34	        }
    35	        return grouped.toString();
    36	    }
    37	}

