    10	public class RespondWithOwner {
    11	
    12	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
    13	            ObjectResponse<OwnerDto> response) {
    14	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
    15	        int namesakeCount = Namesakes.countBefore(owner, ownerRepository);
    16	        dto.setNamesakeCount(namesakeCount);
    17	        int membershipPoints = MembershipLevel.points(owner, namesakeCount, Household.size(owner, ownerRepository));
    18	        dto.setMembershipPoints(membershipPoints);
    19	        dto.setMembershipLevel(MembershipCap.apply(owner, MembershipLevel.level(membershipPoints), ownerRepository));
    20	        dto.setContactPreference(owner.getEmail() != null ? "EMAIL" : "PHONE");
    21	        Integer possibleDuplicateOf = PossibleDuplicate.of(owner, ownerRepository);
    22	        dto.setPossibleDuplicate(possibleDuplicateOf != null);
    23	        dto.setPossibleDuplicateOf(possibleDuplicateOf);
    24	        dto.setSelfLink("/api/owners/" + owner.getId());
    25	        response.send(dto);
    26	    }
